def forward(groups):
    value = float(groups[0])
    unit = groups[1]
    layout = [unit]
    if unit == 'KB':
        value *= 1024
    elif unit == 'MB':
        value *= 1024 * 1024
    elif unit == 'B':
        value = round(value)
    return {'stored': [int(round(value))], 'layout': layout}

def inverse(record):
    value = record['stored'][0]
    unit = record['layout'][0]
    if unit == 'KB':
        value = value / 1024
    elif unit == 'MB':
        value = value / (1024 * 1024)
    return f"{value:.1f} {unit}"
